import MarkdownIt from 'markdown-it';
import {
  GuidanceError,
  GUIDANCE_IMAGE_BYTES,
  type GuidanceUpload,
} from '../types/guidance';
import {
  PROFILE_UPLOAD_BYTES,
  PROFILE_UPLOAD_COUNT,
} from '../types/design-profile';
import { describeProfileImage } from './profiles/ProfileMedia';
import { errorMessage } from '../utils/errorMessage';

interface GuidanceImageReference {
  source: string;
  alt: string;
  title?: string;
}

const parser = new MarkdownIt('commonmark');
parser.validateLink = () => true;

export const guidanceAssetError = (
  source: string,
  reason: string,
): GuidanceError =>
  new GuidanceError(
    'guidance_asset_invalid',
    `Saved context image "${source}": ${reason}`,
  );

export const guidanceImageReferences = (
  markdown: string,
): GuidanceImageReference[] => {
  const collect = (tokens: MarkdownIt.Token[]): GuidanceImageReference[] =>
    tokens.flatMap((token) => {
      if (token.type.startsWith('html') && /<img\b/i.test(token.content))
        throw guidanceAssetError(
          'HTML image',
          'Use a relative Markdown image link to a local PNG, JPEG, WebP or GIF file.',
        );
      if (token.type !== 'image') return collect(token.children ?? []);
      const source = token.attrGet('src') ?? '';
      const decoded = decodeURIComponent(source);
      if (
        !decoded ||
        /^(?:[a-z][a-z\d+.-]*:|[/\\]|#)/i.test(decoded) ||
        /[?#\0]/.test(decoded)
      )
        throw guidanceAssetError(
          source,
          'Use a relative local image file; remote URLs, absolute paths and embedded images are unsupported.',
        );
      const title = token.attrGet('title');
      return [{ source, alt: token.content, ...(title ? { title } : {}) }];
    });
  return collect(parser.parse(markdown, {}));
};

export const validateGuidanceImages = (
  input: Pick<GuidanceUpload, 'markdown' | 'images'>,
) => {
  const references = guidanceImageReferences(input.markdown);
  const sources = new Set(references.map(({ source }) => source));
  const uploads = new Map<
    string,
    { bytes: Buffer; media: ReturnType<typeof describeProfileImage> }
  >();
  const hashes = new Set<string>();
  let size = 0;
  for (const image of input.images ?? []) {
    if (!sources.has(image.source))
      throw guidanceAssetError(
        image.source,
        'Upload is not referenced by the Markdown.',
      );
    if (uploads.has(image.source))
      throw guidanceAssetError(image.source, 'Duplicate upload destination.');
    const match =
      /^data:(image\/(?:png|jpeg|webp|gif));base64,([A-Za-z0-9+/]+={0,2})$/.exec(
        image.dataUrl,
      );
    if (!match)
      throw guidanceAssetError(
        image.source,
        'Unsupported image format or invalid base64 data.',
      );
    const bytes = Buffer.from(match[2], 'base64');
    if (
      bytes.length > GUIDANCE_IMAGE_BYTES ||
      bytes.toString('base64') !== match[2]
    )
      throw guidanceAssetError(
        image.source,
        'Images must use valid base64 and be at most 10 MiB.',
      );
    let media: ReturnType<typeof describeProfileImage>;
    try {
      media = describeProfileImage(bytes);
    } catch (error) {
      throw guidanceAssetError(
        image.source,
        errorMessage(error, 'Unsupported image data.'),
      );
    }
    if (media.mimeType !== match[1])
      throw guidanceAssetError(
        image.source,
        'Image bytes do not match the declared format.',
      );
    uploads.set(image.source, { bytes, media });
    if (hashes.has(media.hash)) continue;
    hashes.add(media.hash);
    size += bytes.length;
    if (size > PROFILE_UPLOAD_BYTES || hashes.size > PROFILE_UPLOAD_COUNT)
      throw guidanceAssetError(
        image.source,
        'Images exceed the 35 MiB or 100-image upload budget.',
      );
  }
  for (const source of sources)
    if (!uploads.has(source))
      throw guidanceAssetError(
        source,
        'Required image was not uploaded. Save it locally and add/update with --file.',
      );
  return { references, uploads };
};
